package mx.elmuelle.pdv;
import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import org.junit.*;import org.junit.runner.RunWith;import static org.junit.Assert.*;import android.app.*;import android.content.*;import android.webkit.*;import org.json.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.lang.reflect.*;import java.util.*;import java.util.concurrent.*;
@RunWith(AndroidJUnit4.class) public class PosOfflineDeviceTest {
 private String origin,token,cookie;private MainActivity activity;
 private JSONObject call(String route,String method,JSONObject body,int expected)throws Exception {HttpURLConnection c=(HttpURLConnection)new URL(origin+route).openConnection();c.setConnectTimeout(10000);c.setReadTimeout(180000);c.setRequestMethod(method);c.setRequestProperty("X-Android-Access",token);if(cookie!=null)c.setRequestProperty("Cookie",cookie);if(body!=null){c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");try(OutputStream out=c.getOutputStream()){out.write(body.toString().getBytes(StandardCharsets.UTF_8));}}int status=c.getResponseCode();InputStream in=status<400?c.getInputStream():c.getErrorStream();ByteArrayOutputStream output=new ByteArrayOutputStream();byte[] bytes=new byte[65536];int n;while((n=in.read(bytes))>0)output.write(bytes,0,n);in.close();String value=output.toString("UTF-8"),setCookie=c.getHeaderField("Set-Cookie");if(setCookie!=null)cookie=setCookie.split(";")[0];c.disconnect();assertEquals(route+" "+value,expected,status);return value.startsWith("[")?new JSONObject().put("items",new JSONArray(value)):new JSONObject(value);}
 private JSONObject obj(Object... fields)throws Exception {JSONObject value=new JSONObject();for(int i=0;i<fields.length;i+=2)value.put((String)fields[i],fields[i+1]);return value;}
 @Test public void isolatedOfflineBusinessFlowsAndRecoveryOnAndroid()throws Exception {
  android.app.Instrumentation instrumentation=InstrumentationRegistry.getInstrumentation();Context context=instrumentation.getTargetContext();activity=(MainActivity)instrumentation.startActivitySync(new Intent(context,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Field originField=MainActivity.class.getDeclaredField("origin"),tokenField=MainActivity.class.getDeclaredField("access");originField.setAccessible(true);tokenField.setAccessible(true);
  boolean ready=false;for(int i=0;i<360;i++){origin=(String)originField.get(null);token=(String)tokenField.get(null);if(origin!=null&&token!=null)try{call("/api/health","GET",null,200);ready=true;break;}catch(Exception|AssertionError ignored){}Thread.sleep(1000);}assertTrue("Node/SQLite local no inició",ready);
  JSONObject initial=call("/api/settings","GET",null,200);assertTrue(initial.getBoolean("setupRequired"));call("/api/setup/owner","POST",obj("name","Administrador sintético Android","pin","584209"),201);assertNotNull(cookie);
  JSONArray products=call("/api/products","GET",null,200).getJSONArray("items");assertEquals(28,products.length());JSONObject piece=null,weighted=null;for(int i=0;i<products.length();i++){JSONObject p=products.getJSONObject(i);assertEquals(0,p.getDouble("stockQuantity"),0);assertTrue(p.has("photoFile"));if(p.getString("unit").equals("pieza"))piece=p;else weighted=p;}assertNotNull(piece);assertNotNull(weighted);assertEquals(0,call("/api/sales","GET",null,200).getJSONArray("items").length());assertEquals(0,call("/api/inventory/entries","GET",null,200).getJSONArray("items").length());
  JSONObject cash=call("/api/cash-sessions/open","POST",obj("openingAmount",100,"responsible","Administrador sintético Android"),201);String cashId=cash.getString("id");
  JSONObject saleBody=obj("checkoutIntentId",UUID.randomUUID().toString(),"cashSessionId",cashId,"items",new JSONArray().put(obj("productId",piece.getString("id"),"quantity",1,"source","manual")),"paymentMethod","efectivo","discount",0);
  call("/api/sales","POST",saleBody,409);
  call("/api/products/"+piece.getString("id")+"/inventory","PATCH",obj("operationId",UUID.randomUUID().toString(),"stockQuantity",5,"reason","Ajuste únicamente sintético del emulador","type","adjustment"),200);
  JSONObject sold=call("/api/sales","POST",saleBody,201);assertEquals(piece.getDouble("price"),sold.getDouble("total"),0.001);JSONObject replay=call("/api/sales","POST",saleBody,200);assertEquals(sold.getString("id"),replay.getString("id"));
  JSONArray after=call("/api/products","GET",null,200).getJSONArray("items");for(int i=0;i<after.length();i++)if(after.getJSONObject(i).getString("id").equals(piece.getString("id")))assertEquals(4,after.getJSONObject(i).getDouble("stockQuantity"),0);
  call("/api/products/"+weighted.getString("id")+"/inventory","PATCH",obj("operationId",UUID.randomUUID().toString(),"stockQuantity",5,"reason","Peso de prueba en el emulador","type","adjustment"),200);
  JSONObject invalidScale=obj("checkoutIntentId",UUID.randomUUID().toString(),"cashSessionId",cashId,"items",new JSONArray().put(obj("productId",weighted.getString("id"),"quantity",1.25,"source","scale")),"paymentMethod","efectivo","discount",0);call("/api/sales","POST",invalidScale,403);call("/api/android/weight-grant","POST",obj("productId",weighted.getString("id"),"quantity",1.25),400);
  JSONObject invalidManual=obj("checkoutIntentId",UUID.randomUUID().toString(),"cashSessionId",cashId,"items",new JSONArray().put(obj("productId",weighted.getString("id"),"quantity",1.25,"source","manual")),"paymentMethod","efectivo","discount",0);call("/api/sales","POST",invalidManual,403);
  JSONObject backup=call("/api/android/backup/export","POST",obj("password","synthetic-recovery"),200);JSONObject wrong=obj("path",backup.getString("path"),"password","incorrect-only");call("/api/android/backup/verify","POST",wrong,400);JSONObject recovered=call("/api/android/backup/verify","POST",obj("path",backup.getString("path"),"password","synthetic-recovery"),200);assertTrue(recovered.getBoolean("integrity"));assertTrue(recovered.getBoolean("allDocumentsPreserved"));assertTrue(recovered.getBoolean("auditPreserved"));assertEquals(28,recovered.getInt("photos"));
  assertFalse(call("/api/support/config","GET",null,200).getBoolean("configured"));JSONObject report=call("/api/support/reports","POST",obj("operationId",UUID.randomUUID().toString(),"kind","sugerencia","description","Prueba Android sin conexión; no se envía al receptor real.","attachments",new JSONArray(),"consentRemote",false),201);assertEquals("local",report.getString("delivery"));assertTrue(report.isNull("receipt"));
  CountDownLatch latch=new CountDownLatch(1);String[] page={null};instrumentation.runOnMainSync(()->{try{Field field=MainActivity.class.getDeclaredField("web");field.setAccessible(true);WebView web=(WebView)field.get(activity);web.evaluateJavascript("JSON.stringify({setup:!!document.getElementById('setupOwnerSubmitBtn'),pos:!!document.getElementById('ticketItems'),bridge:!!window.AndroidShell})",v->{page[0]=v;latch.countDown();});}catch(Exception error){latch.countDown();}});assertTrue(latch.await(30,TimeUnit.SECONDS));assertNotNull(page[0]);assertTrue(page[0].contains("bridge"));
  File db=new File(context.getNoBackupFilesDir(),"pos/data/el-muelle-pos.sqlite");byte[] header=new byte[16];try(InputStream input=new FileInputStream(db)){input.read(header);}assertNotEquals("SQLite format 3\u0000",new String(header,StandardCharsets.US_ASCII));
 }
}
